    let horiz = vec!['<','<','>','>','<'];
    let vert  = vec!['^','v','v','^'];
    let ans = solve(n, m, horiz, vert);
    // prints either "YES\n" or "NO\n"
    std::io::stdout().write_all(&ans).unwrap();
